<script setup lang="ts">
import {ref} from 'vue';import {statusLabels} from '@briochett/contracts';import {useAuth} from '../stores/auth';import {api,errorMessage} from '../api';import {useList} from '../composables';import PageHeader from '../components/PageHeader.vue';import Pagination from '../components/Pagination.vue';
type Command={id:string;number:number;clientName:string;status:string;notes:string;items:{name:string;sku:string;quantity:number}[]};const auth=useAuth(),{data,page,busy,error,load}=useList<Command>(()=>'/commands'),working=ref('');async function advance(k:Command){working.value=k.id;try{await api('/commands/'+k.id+'/advance',{method:'POST'});await load();}catch(e){error.value=errorMessage(e);}finally{working.value='';}}
</script>
<template><PageHeader title="Comandas" description="Preparación de pedidos validados por Administración" /><div class="toolbar"><button class="secondary" :disabled="busy" @click="load">Actualizar comandas</button></div><p v-if="error" class="notice error" role="alert">{{error}}</p><div class="command-grid"><article v-for="k in data.items" :key="k.id" class="card stack"><div class="split"><h2>PED-{{String(k.number).padStart(4,'0')}}</h2><span class="badge" :class="k.status">{{k.status==='pendiente'?'Pendiente':statusLabels[k.status]}}</span></div><h3>{{k.clientName}}</h3><div v-for="line in k.items" :key="line.sku" class="split"><span>{{line.name}}</span><strong>{{line.quantity}} u.</strong></div><p v-if="k.notes" class="notice">{{k.notes}}</p><button v-if="auth.user?.role!=='supervision'&&k.status!=='listo'" :disabled="!!working" @click="advance(k)">{{working===k.id?'Guardando…':k.status==='pendiente'?'Iniciar preparación':'Marcar lista'}}</button></article></div><p v-if="!busy&&!data.items.length" class="card empty">No hay comandas disponibles. Los pedidos deben ser validados por Administración.</p><Pagination :page="page" :total="data.total" :busy="busy" @change="page=$event" /></template>
